 20→/** Get user initials from email or name */
 21→function getInitials(email?: string | null): string {
 22→  if (!email) return "?";
 23→  const name = email.split("@")[0];
 24→  const parts = name.split(/[._-]/);
 25→  if (parts.length >= 2) {
 26→    return (parts[0][0] + parts[1][0]).toUpperCase();
 27→  }
 28→  return name[0]?.toUpperCase() || "?";
 29→}
 30→
 31→const AppHeader = () => {
 32→  const { user, profile, isAdmin, signOut } = useAuth();
 33→  const [authOpen, setAuthOpen] = useState(false);
 34→  const [authTab, setAuthTab] = useState<"signin" | "signup">("signin");
 35→  const navigate = useNavigate();
 36→
 37→  const openAuth = (tab: "signin" | "signup") => {
 38→    setAuthTab(tab);
 39→    setAuthOpen(true);
 40→  };
 41→
 42→  // Calculate total credits
 43→  const subCredits = profile?.subscription_credits ?? 0;
 44→  const topCredits = profile?.topup_credits ?? 0;
 45→  const bonusCredits = profile?.bonus_credits ?? 0;
 46→  const splitTotal = subCredits + topCredits + bonusCredits;
 47→  const legacyCredits = profile?.credits ?? 0;
 48→  const totalCredits = splitTotal > 0 ? splitTotal : legacyCredits;
 49→  const isLowCredits = totalCredits < 3;
 50→
 51→  const initials = getInitials(user?.email);
 52→
 53→  return (
 54→    <>
 55→      <header className="border-b border-border bg-card">
 56→        <div className="mx-auto max-w-[1200px] px-4 sm:px-6 flex items-center justify-between h-14">
 57→          {/* Logo */}
 58→          <Link to="/" className="flex items-center gap-2">
 59→            <Zap className="h-5 w-5 text-primary" />
 60→            <span className="font-semibold text-foreground tracking-tight">Rankora</span>
 61→          </Link>
 62→
 63→          {/* Right side */}
 64→          <div className="flex items-center gap-2">
 65→            <ThemeToggle />
 66→            {user ? (
 67→              <>
 68→                {/* Credits badge */}
 69→                <button
 70→                  onClick={() => navigate("/settings")}
 71→                  className={`group inline-flex items-center gap-1.5 rounded-lg px-3 py-1.5 outline-none focus-visible:ring-2 focus-visible:ring-offset-2 border ${
 72→                    isLowCredits
 73→                      ? "border-destructive/40 text-destructive hover:border-destructive hover:bg-destructive/5 focus-visible:ring-destructive"
 74→                      : "border-border text-foreground hover:border-foreground/40 hover:bg-muted focus-visible:ring-ring"
 75→                  }`}
 76→                >
 77→                  {isLowCredits ? (
 78→                    <AlertTriangle className="h-4 w-4" />
 79→                  ) : (
 80→                    <Wallet className="h-4 w-4 text-muted-foreground" />
 81→                  )}
 82→                  <span className="text-sm font-medium tabular-nums">{totalCredits}</span>
 83→                  <span className="text-[11px] font-medium text-muted-foreground">Credits</span>
 84→                </button>
 85→
 86→                {/* User avatar dropdown */}
 87→                <DropdownMenu>
 88→                  <DropdownMenuTrigger asChild>
 89→                    <button className="h-9 w-9 rounded-lg bg-primary text-primary-foreground text-sm font-bold flex items-center justify-center hover:bg-primary/90 transition-all cursor-pointer outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-1">
 90→                      {initials}
 91→                    </button>
 92→                  </DropdownMenuTrigger>
 93→                  <DropdownMenuContent align="end" className="w-48 mt-1.5">
 94→                    <DropdownMenuItem onClick={() => navigate("/settings")}>
 95→                      <Settings className="h-4 w-4 mr-2" />
 96→                      Settings
 97→                    </DropdownMenuItem>
 98→                    {isAdmin && (
 99→                      <DropdownMenuItem onClick={() => navigate("/admin")}>
100→                        <ShieldCheck className="h-4 w-4 mr-2" />
101→                        Admin
102→                      </DropdownMenuItem>
103→                    )}
104→                    <DropdownMenuSeparator />
105→                    <DropdownMenuItem onClick={() => navigate("/book-demo")}>
106→                      <CalendarCheck className="h-4 w-4 mr-2" />
107→                      Book Demo
108→                    </DropdownMenuItem>
109→                    <DropdownMenuItem onClick={() => navigate("/request-feature")}>
110→                      <Lightbulb className="h-4 w-4 mr-2" />
111→                      Request Feature
112→                    </DropdownMenuItem>
113→                    <DropdownMenuSeparator />
114→                    <DropdownMenuItem onClick={signOut}>
115→                      <LogOut className="h-4 w-4 mr-2" />
116→                      Sign out
117→                    </DropdownMenuItem>
118→                  </DropdownMenuContent>
119→                </DropdownMenu>
120→              </>
121→            ) : (
122→              <>
123→                <Button variant="ghost" size="sm" onClick={() => openAuth("signin")}>
124→                  Sign in
125→                </Button>
126→                <Button size="sm" onClick={() => openAuth("signup")}>
127→                  Sign up free
128→                </Button>
129→              </>
130→            )}
131→          </div>
132→        </div>
133→      </header>
134→      <AuthDialog open={authOpen} onOpenChange={setAuthOpen} defaultTab={authTab} />
135→    </>
136→  );
137→};
138→
139→export default AppHeader;
