 48→interface JobSidebarProps {
 49→  pastJobs: PastJob[];
 50→  selectedJobId: string | null;
 51→  loadingPastJobs: boolean;
 52→  onSelectJob: (jobId: string) => void;
 53→  onNewJob: () => void;
 54→  onRenameJob: (jobId: string, newTitle: string) => void;
 55→  onDeleteJob: (jobId: string) => void;
 56→  onAuthRequired?: () => void;
 57→  isAuthenticated?: boolean;
 58→}
