 60→function getDisplayTitle(job: PastJob): string {
 61→  if (job.title) return job.title;
 62→  const firstLine = job.job_description.trim().split("\n")[0].trim();
 63→  return firstLine.slice(0, 50).trim() || `Job - ${format(new Date(job.created_at), "MMM d, yyyy")}`;
 64→}
 65→
 66→const JobSidebar = ({ pastJobs, selectedJobId, loadingPastJobs, onSelectJob, onNewJob, onRenameJob, onDeleteJob, onAuthRequired, isAuthenticated = true }: JobSidebarProps) => {
 67→  const [search, setSearch] = useState("");
 68→  const [editingId, setEditingId] = useState<string | null>(null);
 69→  const [editValue, setEditValue] = useState("");
 70→  const [deleteJobId, setDeleteJobId] = useState<string | null>(null);
 71→  const editInputRef = useRef<HTMLInputElement>(null);
 72→
 73→  const filteredJobs = useMemo(() => {
 74→    if (!search.trim()) return pastJobs;
 75→    const q = search.toLowerCase();
 76→    return pastJobs.filter(
 77→      (job) =>
 78→        getDisplayTitle(job).toLowerCase().includes(q) ||
 79→        job.job_description.toLowerCase().includes(q)
 80→    );
 81→  }, [pastJobs, search]);
 82→
 83→  useEffect(() => {
 84→    if (editingId && editInputRef.current) {
 85→      editInputRef.current.focus();
 86→      editInputRef.current.select();
 87→    }
 88→  }, [editingId]);
 89→
 90→  const startEditing = (job: PastJob) => {
 91→    setEditingId(job.id);
 92→    setEditValue(getDisplayTitle(job));
 93→  };
 94→
 95→  const saveRename = async () => {
 96→    if (!editingId || !editValue.trim()) {
 97→      setEditingId(null);
 98→      return;
 99→    }
100→    try {
101→      const { error } = await supabase
102→        .from("jobs")
103→        .update({ title: editValue.trim() } as any)
104→        .eq("id", editingId);
105→      if (error) throw error;
106→      onRenameJob(editingId, editValue.trim());
107→      toast.success("Job renamed");
108→    } catch {
109→      toast.error("Failed to rename job");
110→    }
111→    setEditingId(null);
112→  };
113→
114→  const cancelEditing = () => setEditingId(null);
115→
116→  const confirmDelete = () => {
117→    if (deleteJobId) {
118→      onDeleteJob(deleteJobId);
119→      setDeleteJobId(null);
120→    }
121→  };
122→
123→  return (
124→    <>
125→      <Sidebar collapsible="offcanvas" className="border-r border-sidebar-border">
126→        <SidebarHeader className="p-4 space-y-3">
127→          <Button onClick={() => { if (!isAuthenticated && onAuthRequired) { onAuthRequired(); return; } onNewJob(); }} className="w-full gap-2" size="sm">
128→            <Plus className="h-4 w-4" />
129→            New Job
130→          </Button>
131→          <div className="relative">
132→            <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-muted-foreground" />
133→            <SidebarInput
134→              placeholder="Search jobs…"
135→              value={search}
136→              onChange={(e) => setSearch(e.target.value)}
137→              className="pl-8"
138→            />
139→          </div>
140→        </SidebarHeader>
141→
142→        <SidebarContent>
143→          <SidebarGroup>
144→            <SidebarGroupLabel className="px-4 flex items-center gap-2">
145→              <Briefcase className="h-4 w-4" />
146→              <span>Job History</span>
147→              {search && <span className="ml-auto text-[11px]">({filteredJobs.length})</span>}
148→            </SidebarGroupLabel>
149→            <SidebarGroupContent>
150→              {!isAuthenticated ? (
151→                <div className="px-3 py-3">
152→                  <button
153→                    onClick={() => onAuthRequired?.()}
154→                    className="w-full rounded-lg border border-dashed border-border px-3 py-5 text-center hover:border-primary/50 hover:bg-primary/5 transition-all group"
155→                  >
156→                    <Briefcase className="h-5 w-5 text-muted-foreground group-hover:text-primary mx-auto mb-2 transition-colors" />
157→                    <p className="text-xs font-medium text-foreground mb-1">No jobs yet</p>
158→                    <p className="text-[11px] text-muted-foreground mb-3">Sign in to view your job history and ranked results</p>
159→                    <span className="inline-flex items-center gap-1.5 text-xs font-semibold text-primary">
160→                      Sign in to get started →
161→                    </span>
162→                  </button>
163→                </div>
164→              ) : loadingPastJobs ? (
165→                <div className="space-y-1.5 px-2">
166→                  {[0, 1, 2].map((i) => (
167→                    <div key={i} className="rounded-lg border border-sidebar-border bg-sidebar-accent/50 p-3 space-y-2" style={{ animationDelay: `${i * 80}ms`, animationFillMode: "backwards" }}>
168→                      <Skeleton className="h-4 w-3/4 bg-sidebar-accent" />
169→                      <div className="flex items-center justify-between">
170→                        <Skeleton className="h-3 w-20 bg-sidebar-accent" />
171→                        <Skeleton className="h-3 w-24 bg-sidebar-accent" />
172→                      </div>
173→                    </div>
174→                  ))}
175→                </div>
176→              ) : filteredJobs.length === 0 ? (
177→                <p className="text-sm text-muted-foreground px-4 py-6 text-center">
178→                  {search ? "No matching jobs found." : "No jobs yet. Create your first one!"}
179→                </p>
180→              ) : (
181→                <SidebarMenu className="space-y-1.5 px-2">
182→                  {filteredJobs.map((job, i) => (
183→                    <SidebarMenuItem key={job.id} className="animate-in fade-in slide-in-from-left-2 duration-200" style={{ animationDelay: `${i * 40}ms`, animationFillMode: "backwards" }}>
184→                      {editingId === job.id ? (
185→                        <div className="mx-0 rounded-lg border border-primary/50 bg-card shadow-sm px-3 py-2">
186→                          <Input
187→                            ref={editInputRef}
188→                            value={editValue}
189→                            onChange={(e) => setEditValue(e.target.value)}
190→                            onKeyDown={(e) => {
191→                              if (e.key === "Enter") saveRename();
192→                              if (e.key === "Escape") cancelEditing();
193→                            }}
194→                            onBlur={saveRename}
195→                            className="h-7 text-sm"
196→                          />
197→                        </div>
198→                      ) : (
199→                        <SidebarMenuButton
200→                          isActive={selectedJobId === job.id}
201→                          onClick={() => onSelectJob(job.id)}
202→                          className={cn(
203→                            "flex flex-col items-start gap-1 h-auto py-2.5 px-3 group/item",
204→                            "rounded-lg border transition-colors",
205→                            selectedJobId === job.id
206→                              ? "border-l-2 border-l-primary bg-sidebar-accent"
207→                              : "border-transparent hover:bg-sidebar-accent/50"
208→                          )}
209→                        >
210→                          <div className="flex items-center gap-1 w-full">
211→                            <span className="text-sm leading-snug line-clamp-2 flex-1">
212→                              {getDisplayTitle(job)}
213→                            </span>
214→                            <DropdownMenu>
215→                              <DropdownMenuTrigger asChild onClick={(e) => e.stopPropagation()}>
216→                                <button className="opacity-0 group-hover/item:opacity-100 transition-opacity p-0.5 rounded hover:bg-accent shrink-0">
217→                                  <MoreHorizontal className="h-3.5 w-3.5 text-muted-foreground" />
218→                                </button>
219→                              </DropdownMenuTrigger>
220→                              <DropdownMenuContent align="end" className="w-36">
221→                                <DropdownMenuItem onClick={(e) => { e.stopPropagation(); startEditing(job); }}>
222→                                  <Pencil className="h-3.5 w-3.5 mr-2" />
223→                                  Rename
224→                                </DropdownMenuItem>
225→                                <DropdownMenuItem
226→                                  onClick={(e) => { e.stopPropagation(); setDeleteJobId(job.id); }}
227→                                  className="text-destructive focus:text-destructive"
228→                                >
229→                                  <Trash2 className="h-3.5 w-3.5 mr-2" />
230→                                  Delete
231→                                </DropdownMenuItem>
232→                              </DropdownMenuContent>
233→                            </DropdownMenu>
234→                          </div>
235→                          <div className="flex items-center gap-2 w-full">
236→                            <span className="text-[11px] text-muted-foreground flex items-center gap-0.5">
237→                              <FileText className="h-2.5 w-2.5" />
238→                              {job.resume_count} {job.resume_count === 1 ? "resume" : "resumes"}
239→                            </span>
240→                            <span className="text-[11px] text-muted-foreground flex items-center gap-0.5 ml-auto">
241→                              <Clock className="h-2.5 w-2.5" />
242→                              {format(new Date(job.created_at), "MMM d, yyyy")}
243→                            </span>
244→                          </div>
245→                        </SidebarMenuButton>
246→                      )}
247→                    </SidebarMenuItem>
248→                  ))}
249→                </SidebarMenu>
250→              )}
251→            </SidebarGroupContent>
252→          </SidebarGroup>
253→        </SidebarContent>
254→      </Sidebar>
255→
256→      <AlertDialog open={!!deleteJobId} onOpenChange={(open) => !open && setDeleteJobId(null)}>
257→        <AlertDialogContent>
258→          <AlertDialogHeader>
259→            <AlertDialogTitle>Delete this job?</AlertDialogTitle>
260→            <AlertDialogDescription>
261→              This will permanently delete this job and all its resumes. This action cannot be undone.
262→            </AlertDialogDescription>
263→          </AlertDialogHeader>
264→          <AlertDialogFooter>
265→            <AlertDialogCancel>Cancel</AlertDialogCancel>
266→            <AlertDialogAction onClick={confirmDelete} className="bg-destructive text-destructive-foreground hover:bg-destructive/90">
267→              Delete
268→            </AlertDialogAction>
269→          </AlertDialogFooter>
270→        </AlertDialogContent>
271→      </AlertDialog>
272→    </>
273→  );
274→};
275→
276→export default JobSidebar;
